pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // We aim to minimize the score.
    // 1. Base Score: We prefer smaller post_residual (Best Fit).
    // 2. Penalty for creating "slivers" (very small residual) that are hard to fill.
    //    Quadratic penalty on small post_residual values to avoid leaving useless space.
    let sliver_penalty = if post_res < 10.0 && post_res > 0.0 {
        (10.0 - post_res).powi(2) * 5.0
    } else {
        0.0
    };

    // 3. Lookahead coupling: If next_item_size exists, favor bins that can accommodate it.
    //    If post_residual is smaller than next_item_size, we penalize the bin.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 2.0
    } else {
        0.0
    };

    // 4. Dynamic thresholding based on stream progress:
    //    As we approach the end of the stream, prioritize closing bins (lower residual)
    //    more aggressively by scaling the post_residual impact.
    let progress_weight = 1.0 + (progress * 2.0);

    // 5. If this is the only fitting bin, we reduce its cost to avoid opening a new bin unnecessarily.
    let scarcity_bonus = if fitting_bins_count == 1 { -50.0 } else { 0.0 };

    // 6. Penalty for opening a new bin (bin_residual == bin_capacity)
    //    Increase cost of new bin as we progress to force consolidation.
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 + (progress * 100.0)
    } else {
        0.0
    };

    let score = (post_res * progress_weight) 
        + sliver_penalty 
        + lookahead_penalty 
        + scarcity_bonus 
        + new_bin_penalty;

    score
}

