pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64 + 1.0);

    // Penalize creating "fragmented" space (small, unusable residuals)
    // Residuals between 1 and 9 are extremely difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if we have a next item, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward bins that keep capacity for the next item
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 15.0; // Penalize "blocking" the next item
        }
    }

    // Global state pressure: if many bins are open, we want to consolidate (Best Fit).
    // If few bins are open, we can afford to be more selective.
    let density_penalty = (open_bins_count as f64) * 2.5;
    score += density_penalty;

    // Dynamic Threshold for opening new bins:
    // If bin_residual == bin_capacity (New Bin Candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is high (we are wasting space)
        // or if we are nearing the end of the stream and need to clear out.
        let waste_factor = mean_residual / bin_capacity as f64;
        let urgency = progress * 10.0;

        // Base cost for opening a new bin is high to encourage packing.
        score = 45.0 + (waste_factor * 20.0) - urgency;
    } else {
        // If it's an existing bin, favor those that move the residual closer to the global mean
        // to keep bin utilization uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Criticality: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Adaptive New Bin Penalty: Heavily discourage new bins unless necessary.
    // Scale penalty by the ratio of bins currently open to total items processed.
    if is_new_bin {
        let utilization_factor = (open_bins_count as f64 / (step_index + 1) as f64) * 120.0;
        score += 155.0 + utilization_factor + (progress * 80.0) + (mean_residual * 0.8);
    } else {
        // 2. Precision Packing: Reward near-perfect fits exponentially.
        if post_residual == 0 {
            score -= 220.0;
        } else if post_residual < 12 {
            // Penalize small "dead zones" more aggressively than the parent.
            score += (14.0 - post_residual as f64).powi(2) * 1.5;
        }
    }

    // 3. Lookahead Coupling: Prioritize bins that swallow the next item perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let remainder = post_residual - next_item_size;
            score -= 135.0; // Base reward for accommodating next item
            if remainder == 0 { score -= 90.0; } // Perfect double-fit
            if remainder >= 25 && remainder <= 45 { score -= 55.0; } // Flexibility bonus
        } else {
            // Penalty for stranding space unusable for the next item, non-linear.
            let waste_ratio = post_residual as f64 / next_item_size as f64;
            score += 110.0 * (1.0 - waste_ratio.powf(0.7));
        }
    }

    // 4. Fragmentation Control: Focus on medium-sized dead zones.
    if post_residual >= 6 && post_residual <= 20 {
        score += 95.0 - (post_residual as f64 - 13.0).abs() * 5.0;
    }

    // 5. Dynamic Mean Deviation: Force convergence toward the mean residual.
    if mean_residual > 0.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * (0.6 + progress * 1.5);
    }

    // 6. Scarcity Constraint: Force consolidation when options are limited.
    if fitting_bins_count > 0 && fitting_bins_count <= 3 {
        score -= 180.0 / (fitting_bins_count as f64);
    }

    // 7. Temporal Pressure: Aggressive final-stage compaction.
    score += (progress.powf(2.5)) * 210.0;

    // 8. Residual normalization: Penalize large remaining capacities.
    score += (post_residual as f64 / bin_capacity as f64) * 35.0;

    score
}
